import{_ as l,a0 as d,w as p,s as o,ao as r,I as n,x as i,a1 as a,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何在 Linux 上永久挂载一个 Windows 共享 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上永久挂载一个 Windows 共享 | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上永久挂载一个 Windows 共享 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上永久挂载一个 Windows 共享 | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160624 How to permanently mount a Windows share on Linux","title":"如何在 Linux 上永久挂载一个 Windows 共享","tag":"201607","desc":""},"relativePath":"201607/20160624 How to permanently mount a Windows share on Linux.md","filePath":"[post].md"}'),h={name:"201607/20160624 How to permanently mount a Windows share on Linux.md"};function u(g,s,b,c,k,f){const e=d("Link");return p(),o("div",null,[s[15]||(s[15]=r(`<h1 id="如何在-linux-上永久挂载一个-windows-共享" tabindex="-1">如何在 Linux 上永久挂载一个 Windows 共享 <a class="header-anchor" href="#如何在-linux-上永久挂载一个-windows-共享" aria-label="Permalink to “如何在 Linux 上永久挂载一个 Windows 共享”">​</a></h1><blockquote><p>如果你已经厌倦了每次重启 Linux 就得重新挂载 Windows 共享，读读这个让共享永久挂载的简单方法。</p></blockquote><p><img src="http://tr2.cbsistatic.com/hub/i/2016/06/02/e965310b-b38d-43e6-9eac-ea520992138b/68fd9ec5d6731cc405bdd27f2f42848d/linuxadminhero.jpg" alt=""></p><p><em>图片： Jack Wallen</em></p><p>在 Linux 上和一个 Windows 网络进行交互从来就不是件轻松的事情。想想多少企业正在采用 Linux，需要在这两个平台上彼此协作。幸运的是，有了一些工具的帮助，你可以轻松地将 Windows 网络驱动器映射到一台 Linux 机器上，甚至可以确保在重启 Linux 机器之后共享还在。</p><h3 id="在我们开始之前" tabindex="-1">在我们开始之前 <a class="header-anchor" href="#在我们开始之前" aria-label="Permalink to “在我们开始之前”">​</a></h3><p>要实现这个，你需要用到命令行。过程十分简单，但你需要编辑 /etc/fstab 文件，所以小心操作。还有，我假设你已经让 Samba 正常工作了，可以手动从 Windows 网络挂载共享到你的 Linux 机器，还知道这个共享的主机 IP 地址。</p><p>准备好了吗？那就开始吧。</p><h3 id="创建你的挂载点" tabindex="-1">创建你的挂载点 <a class="header-anchor" href="#创建你的挂载点" aria-label="Permalink to “创建你的挂载点”">​</a></h3><p>我们要做的第一件事是创建一个文件夹，他将作为共享的挂载点。为了简单起见，我们将这个文件夹命名为 share，放在 /media 之下。打开你的终端执行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mkdir /media/share</span></span></code></pre></div><h3 id="安装一些软件" tabindex="-1">安装一些软件 <a class="header-anchor" href="#安装一些软件" aria-label="Permalink to “安装一些软件”">​</a></h3><p>现在我们得安装允许跨平台文件共享的系统；这个系统是 cifs-utils。在终端窗口输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install cifs-utils</span></span></code></pre></div><p>这个命令同时还会安装 cifs-utils 所有的依赖。</p><p>安装完成之后，打开文件 /etc/nsswitch.conf 并找到这一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>hosts: files mdns4_minimal [NOTFOUND=return] dns</span></span></code></pre></div><p>编辑这一行，让它看起来像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>hosts: files mdns4_minimal [NOTFOUND=return] wins dns</span></span></code></pre></div><p>现在你需要安装 windbind 让你的 Linux 机器可以在 DHCP 网络中解析 Windows 机器名。在终端里执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install libnss-windbind windbind</span></span></code></pre></div><p>用这个命令重启网络服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo service networking restart</span></span></code></pre></div><h3 id="挂载网络驱动器" tabindex="-1">挂载网络驱动器 <a class="header-anchor" href="#挂载网络驱动器" aria-label="Permalink to “挂载网络驱动器”">​</a></h3><p>现在我们要映射网络驱动器。这里我们必须编辑 /etc/fstab 文件。在你做第一次编辑之前，用这个命令备份以下这个文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo cp /etc/fstab /etc/fstab.old</span></span></code></pre></div><p>如果你需要恢复这个文件，执行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mv /etc/fstab.old /etc/fstab</span></span></code></pre></div><p>在你的主目录创建一个认证信息文件 .smbcredentials。在这个文件里添加你的用户名和密码，就像这样（USER 和 PASSWORD 替换为实际的用户名和密码）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>username=USER</span></span>
<span class="line"><span></span></span>
<span class="line"><span>password=PASSWORD</span></span></code></pre></div><p>你需要知道挂载这个驱动器的用户的组 ID（GID）和用户 ID（UID）。执行命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>id USER</span></span></code></pre></div><p>USER 是你的实际用户名，你应该会看到类似这样的信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>uid=1000(USER) gid=1000(GROUP)</span></span></code></pre></div><p>USER 是实际的用户名，GROUP 是组名。在（USER）和（GROUP）之前的数字将会被用在 /etc/fstab 文件之中。</p><p>是时候编辑 /etc/fstab 文件了。在你的编辑器中打开那个文件并添加下面这行到文件末尾（替换以下全大写字段以及远程机器的 IP 地址）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>//192.168.1.10/SHARE /media/share cifs credentials=/home/USER/.smbcredentials,iocharset=uft8,gid=GID,udi=UID,file_mode=0777,dir_mode=0777 0 0</span></span></code></pre></div><p><strong>注意</strong>：上面这些内容应该在同一行上。</p><p>保存并关闭那个文件。执行 sudo mount -a 命令，共享将被挂载。检查一下 /media/share，你应该能看到那个网络共享上的文件和文件夹了。</p><h3 id="共享很简单" tabindex="-1">共享很简单 <a class="header-anchor" href="#共享很简单" aria-label="Permalink to “共享很简单”">​</a></h3><p>有了 cifs-utils 和 Samba，映射网络共享在一台 Linux 机器上简单得让人难以置信。现在，你再也不用在每次机器启动的时候手动重新挂载那些共享了。</p>`,41)),n("p",null,[s[1]||(s[1]=i("更多网络提示和技巧，订阅我们的 Data Center 消息吧。 ",-1)),a(e,{href:"https://secure.techrepublic.com/user/login/?regSource=newsletter-button&position=newsletter-button&appId=true&redirectUrl=http%3A%2F%2Fwww.techrepublic.com%2Farticle%2Fhow-to-permanently-mount-a-windows-share-on-linux%2F&"},{default:t(()=>[...s[0]||(s[0]=[i("订阅",-1)])]),_:1})]),s[16]||(s[16]=n("hr",null,null,-1)),n("p",null,[s[3]||(s[3]=i("via: ",-1)),a(e,{href:"http://www.techrepublic.com/article/how-to-permanently-mount-a-windows-share-on-linux/"},{default:t(()=>[...s[2]||(s[2]=[i("http://www.techrepublic.com/article/how-to-permanently-mount-a-windows-share-on-linux/",-1)])]),_:1})]),n("p",null,[s[7]||(s[7]=i("作者：",-1)),a(e,{href:"http://www.techrepublic.com/search/?a=jack+wallen"},{default:t(()=>[...s[4]||(s[4]=[i("Jack Wallen",-1)])]),_:1}),s[8]||(s[8]=i(" 译者：",-1)),a(e,{href:"https://github.com/alim0x"},{default:t(()=>[...s[5]||(s[5]=[i("alim0x",-1)])]),_:1}),s[9]||(s[9]=i(" 校对：",-1)),a(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[6]||(s[6]=[i("wxy",-1)])]),_:1})]),n("p",null,[s[12]||(s[12]=i("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[i("LCTT",-1)])]),_:1}),s[13]||(s[13]=i(" 原创编译，",-1)),a(e,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[i("Linux中国",-1)])]),_:1}),s[14]||(s[14]=i(" 荣誉推出",-1))])])}const y=l(h,[["render",u]]);export{x as __pageData,y as default};
